use vstd::prelude::*;

verus! {
    fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
        requires
            list.len() > 0,
            0 < n < list.len(),
        ensures
            new_list.len() == list.len() &&
            forall|i: usize| 0 <= i < n ==> new_list[i] == list[i + (list.len() - n)] &&
            forall|i: usize| n <= i < list.len() ==> new_list[i] == list[i - n]
    {
        let mut new_list: Vec<i32> = vec![0; list.len()]; // Initialize a new vector with the same length

        // Fill the first part of new_list
        for i in 0..n {
            new_list[i] = list[i + (list.len() - n)];
        }

        // Fill the second part of new_list
        for i in n..list.len() {
            new_list[i] = list[i - n];
        }

        new_list // Return the new list
    }
}

